from pathlib import Path
import json

ROOT=Path('.')
def read(p): return (ROOT/p).read_text(encoding='utf-8')
def write(p,s): (ROOT/p).write_text(s,encoding='utf-8')
def block(text,start,end,repl,label):
    i=text.find(start)
    if i<0: raise RuntimeError(f'{label}: start not found')
    j=text.find(end,i)
    if j<0: raise RuntimeError(f'{label}: end not found')
    return text[:i]+repl+text[j:]
def once(text,old,new,label):
    n=text.count(old)
    if n!=1: raise RuntimeError(f'{label}: expected 1, got {n}')
    return text.replace(old,new,1)

