new_dashboard=r'''function dashboard(){const now=Date.now()/1000,today=S.bookings.filter(b=>date(b.starts_at)===day()),futureRows=S.bookings.filter(future).sort((a,b)=>a.starts_at-b.starts_at),next=futureRows[0],earned=today.filter(b=>b.status!=='cancelled').reduce((a,b)=>a+b.price,0);const attention=futureRows.filter(b=>b.status==='pending'||b.attendance_state==='not_coming'||(b.attendance_state!=='coming'&&b.starts_at-now<=7200));const reason=b=>b.attendance_state==='not_coming'?['danger','Клиент сообщил, что не придёт']:b.status==='pending'?['warn','Новая запись — подтвердите её']:['muted','Скоро визит — клиент ещё не ответил'];const attentionBlock=attention.length?`<section class="attention-panel"><div class="attention-head"><div><span class="eyebrow">ВАЖНО СЕЙЧАС</span><h2>Требуют внимания</h2></div><strong>${attention.length}</strong></div><div class="attention-list">${attention.slice(0,4).map(b=>{const q=reason(b);return `<article class="attention-row"><div class="attention-main"><strong>${time(b.starts_at)} · ${esc(b.name)}</strong><span>${dateLabel(date(b.starts_at))} · ${esc(b.service_name)}</span><small class="attention-reason ${q[0]}">${q[1]}</small></div><div class="attention-actions">${b.status==='pending'?`<button class="primary compact" data-status="confirmed" data-id="${b.id}">Подтвердить</button>`:''}<button class="secondary compact" data-visit="${b.id}">Открыть</button>${b.phone?`<a class="text-button compact" href="tel:${esc(String(b.phone).replace(/[^+0-9]/g,''))}">Связаться</a>`:''}</div></article>`}).join('')}</div></section>`:'';const nextBlock=next?(()=>{const att=attendanceInfo(next),duration=Math.round((next.ends_at-next.starts_at)/60),phone=String(next.phone||'').replace(/[^+0-9]/g,'');return `<section class="next-visit"><div class="next-visit-head"><span class="eyebrow">СЛЕДУЮЩАЯ ЗАПИСЬ</span><span class="next-countdown">${until(next.starts_at)}</span></div><div class="next-visit-body"><div class="next-time"><strong>${time(next.starts_at)}</strong><span>${dateLabel(date(next.starts_at))}</span></div><div class="next-person"><h2>${esc(next.name)}</h2><p>${esc(next.service_name)}</p><div class="next-facts"><span>${duration} мин</span><span>${money(next.price)}</span></div></div><div class="next-statuses"><span class="badge ${next.status}">${labels[next.status]}</span><span class="attendance ${att[0]}">${att[1]}</span></div></div><div class="next-actions"><button class="primary" data-visit="${next.id}">Открыть запись</button>${phone?`<a class="next-contact" href="tel:${esc(phone)}">Связаться</a>`:''}</div></section>`})():`<div class="dashboard-empty"><h3>Сегодня записей нет 👋</h3><p>Свободные окна доступны клиентам для онлайн-записи.</p><div class="actions"><button class="primary" data-page="share">Поделиться ссылкой</button><button class="secondary" data-manual>＋ Добавить запись</button></div></div>`;return `${heading('Добрый день, '+S.own.name,'Сегодня · '+dateLabel(day()))}<section class="today-summary"><div><span>Записей сегодня</span><strong>${today.filter(active).length}</strong></div><div><span>Стоимость записей</span><strong>${money(earned)}</strong></div><div><span>Вариантов времени</span><strong id="free-count">…</strong><small id="free-label"></small></div></section>${attentionBlock}${nextBlock}<div class="section-heading"><h2>Быстрые действия</h2></div><div class="quick-grid"><button data-manual>${icon('calendar')}Добавить запись</button><button data-edit-service="new">${icon('grid')}Добавить услугу</button><button data-page="share">${icon('link')}Моя ссылка</button><button id="block-time">${icon('clock')}Закрыть время</button></div><div class="section-heading"><h2>Записи на сегодня</h2><button data-page="calendar" class="text-button">Все →</button></div>${today.filter(b=>b.status!=='cancelled').sort((a,b)=>a.starts_at-b.starts_at).map(b=>bookingCard(b,true)).join('')||'<div class="dashboard-empty"><h3>На сегодня всё свободно</h3><p>Можно поделиться ссылкой или добавить запись вручную.</p></div>'}`}
'''
